// Извлечение данных из запроса
const userData = $json.data;
const documentType = userData.document_type;
const userId = $json.user_id;

return {
  json: {
    userId,
    documentType,
    courtName: userData.input_data.court_name,
    plaintiff: userData.input_data.plaintiff,
    defendant: userData.input_data.defendant,
    circumstances: userData.input_data.circumstances,
    legalBasis: userData.input_data.legal_basis || '',
    claims: userData.input_data.claims.join('\n'),
  }
}

// Загрузка промпта из файла
const fs = require('fs');
const path = require('path');

const documentType = $json.documentType;
const promptPath = path.join('/app/prompts', 'document-generator', `${documentType}.txt`);

let prompt = '';
try {
  prompt = fs.readFileSync(promptPath, 'utf8');
} catch (error) {
  prompt = fs.readFileSync(path.join('/app/prompts', 'document-generator', 'claim.txt'), 'utf8');
}

// Замена плейсхолдеров
prompt = prompt
  .replace('{{COURT_NAME}}', $json.courtName)
  .replace('{{PLAINTIFF_NAME}}', $json.plaintiff.name)
  .replace('{{PLAINTIFF_INN}}', $json.plaintiff.inn || 'не указан')
  .replace('{{PLAINTIFF_ADDRESS}}', $json.plaintiff.address || 'не указан')
  .replace('{{DEFENDANT_NAME}}', $json.defendant.name)
  .replace('{{DEFENDANT_INN}}', $json.defendant.inn || 'не указан')
  .replace('{{DEFENDANT_ADDRESS}}', $json.defendant.address || 'не указан')
  .replace('{{CIRCUMSTANCES}}', $json.circumstances)
  .replace('{{LEGAL_BASIS}}', $json.legalBasis)
  .replace('{{CLAIMS}}', $json.claims);

return {
  json: {
    ...$json,
    prompt,
  }
}

// Валидация ответа AI
const content = $json.content;

// Проверка на пустой ответ
if (!content || content.trim().length === 0) {
  throw new Error('AI вернул пустой ответ');
}

// Проверка на наличие ключевых слов
const requiredKeywords = ['иск', 'заяв', 'треб', 'суд'];
const hasKeywords = requiredKeywords.some(keyword => 
  content.toLowerCase().includes(keyword)
);

// Структурирование ответа
return {
  json: {
    userId: $json.userId,
    documentType: $json.documentType,
    generatedContent: content,
    status: 'completed',
    tokensUsed: $json.usage?.total_tokens || 0,
    timestamp: new Date().toISOString(),
  }
}

// Форматирование финального ответа
const response = {
  document_id: require('uuid').v4(),
  status: $json.status,
  content: $json.generatedContent,
  tokens_used: $json.tokensUsed,
  created_at: $json.timestamp,
};

return {
  json: response
}
